-- ============================================================================
-- V2 — Programmes académiques
--
-- Objectif : représenter les programmes d'étude, leurs versions dans le temps
--             et les inscriptions des étudiants à ces versions.
--
-- Correspondance domaine -> tables :
--   AcademicProgram    -> academic_program
--   ProgramVersion     -> program_version
--   ProgramEnrollment  -> program_enrollment
--
-- Conventions (AGENTS.md) :
--   * Commentaires en français, identifiants SQL en anglais.
--   * Clés techniques en bigint GENERATED BY DEFAULT AS IDENTITY.
--   * Contraintes nommées pk_ / fk_ / uq_ / ck_.
--   * Statuts stockés en varchar avec CHECK, sans enum PostgreSQL.
--   * Les règles temporelles supplémentaires restent à la charge de l'application.
-- ============================================================================

CREATE TABLE academic_program (
    id     bigint      GENERATED BY DEFAULT AS IDENTITY,
    code   varchar(20) NOT NULL,
    name   varchar(200) NOT NULL,
    status varchar(20) NOT NULL,
    CONSTRAINT pk_academic_program PRIMARY KEY (id),
    CONSTRAINT uq_academic_program_code UNIQUE (code),
    CONSTRAINT ck_academic_program_status CHECK (status IN ('ACTIVE', 'INACTIVE'))
);

CREATE TABLE program_version (
    id            bigint      GENERATED BY DEFAULT AS IDENTITY,
    program_id    bigint      NOT NULL,
    code          varchar(20) NOT NULL,
    effective_from date       NOT NULL,
    effective_to   date,
    status         varchar(20) NOT NULL,
    CONSTRAINT pk_program_version PRIMARY KEY (id),
    CONSTRAINT fk_program_version_academic_program FOREIGN KEY (program_id)
        REFERENCES academic_program (id) ON DELETE CASCADE,
    CONSTRAINT uq_program_version_program_code UNIQUE (program_id, code),
    CONSTRAINT ck_program_version_status CHECK (status IN ('DRAFT', 'ACTIVE', 'ARCHIVED')),
    CONSTRAINT ck_program_version_effective_dates
        CHECK (effective_to IS NULL OR effective_to >= effective_from)
);

CREATE TABLE program_enrollment (
    id                 bigint      GENERATED BY DEFAULT AS IDENTITY,
    student_id         bigint      NOT NULL,
    program_version_id bigint      NOT NULL,
    start_date         date        NOT NULL,
    end_date           date,
    status             varchar(20) NOT NULL,
    CONSTRAINT pk_program_enrollment PRIMARY KEY (id),
    CONSTRAINT fk_program_enrollment_student FOREIGN KEY (student_id)
        REFERENCES student (id) ON DELETE CASCADE,
    CONSTRAINT fk_program_enrollment_program_version FOREIGN KEY (program_version_id)
        REFERENCES program_version (id) ON DELETE CASCADE,
    CONSTRAINT ck_program_enrollment_status
        CHECK (status IN ('ACTIVE', 'COMPLETED', 'WITHDRAWN')),
    CONSTRAINT ck_program_enrollment_dates
        CHECK (end_date IS NULL OR end_date >= start_date)
);

CREATE INDEX ix_program_version_program ON program_version (program_id);
CREATE INDEX ix_program_enrollment_student ON program_enrollment (student_id);
CREATE INDEX ix_program_enrollment_program_version ON program_enrollment (program_version_id);

CREATE UNIQUE INDEX uq_program_enrollment_active_student_version
    ON program_enrollment (student_id, program_version_id)
    WHERE status = 'ACTIVE';

-- ============================================================================
-- Règles de gestion relevant de l'application :
--
-- 1. Une version ACTIVE doit appartenir à un programme ACTIVE ; la cohérence
--    entre ces statuts doit être vérifiée avant modification ou création.
-- 2. Le chevauchement de plusieurs inscriptions ACTIVE pour un étudiant et
--    une même version est interdit par l'index unique partiel ci-dessus.
-- 3. La fin d'une inscription ne doit pas précéder son début ; cette règle est
--    garantie par ck_program_enrollment_dates.
-- ============================================================================
